import{_ as t,o as n,c as o,a5 as i}from"./chunks/framework.Cooo9kuv.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{"标题":"880-批量pdf文件内容提取到excel工具-只支持文本类型-可模板定制","日期":"2026-04-14T00:00:00.000Z","修改日期":"2026-04-14T00:00:00.000Z","作者":"softbangong","状态":"publish","分类":["PDF批处理"],"标签":["PDF信息提取工具","PDF发票提取","PDF字段提取","Python PDF处理","办公自动化工具","发票信息管理","发票数据录入","批量PDF处理","文档自动化处理","模板化提取"]},"headers":[{"level":3,"title":"功能特点","slug":"功能特点","link":"#功能特点","children":[]},{"level":3,"title":"快速开始","slug":"快速开始","link":"#快速开始","children":[]},{"level":3,"title":"详细使用说明","slug":"详细使用说明","link":"#详细使用说明","children":[{"level":4,"title":"主界面功能","slug":"主界面功能","link":"#主界面功能","children":[]},{"level":4,"title":"模板定制功能","slug":"模板定制功能","link":"#模板定制功能","children":[]},{"level":4,"title":"批量处理功能","slug":"批量处理功能","link":"#批量处理功能","children":[]},{"level":4,"title":"结果导出","slug":"结果导出","link":"#结果导出","children":[]}]},{"level":3,"title":"使用场景示例","slug":"使用场景示例","link":"#使用场景示例","children":[{"level":4,"title":"场景一：处理供应商发票","slug":"场景一-处理供应商发票","link":"#场景一-处理供应商发票","children":[]},{"level":4,"title":"场景二：整理报销单据","slug":"场景二-整理报销单据","link":"#场景二-整理报销单据","children":[]},{"level":4,"title":"场景三：合同信息归档","slug":"场景三-合同信息归档","link":"#场景三-合同信息归档","children":[]}]},{"level":3,"title":"注意事项","slug":"注意事项","link":"#注意事项","children":[]},{"level":3,"title":"程序截图","slug":"程序截图","link":"#程序截图","children":[]},{"level":3,"title":"效果展示","slug":"效果展示","link":"#效果展示","children":[]},{"level":3,"title":"常见问题解答","slug":"常见问题解答","link":"#常见问题解答","children":[]},{"level":3,"title":"程序使用环境及相关说明","slug":"程序使用环境及相关说明","link":"#程序使用环境及相关说明","children":[]},{"level":3,"title":"程序使用说明","slug":"程序使用说明","link":"#程序使用说明","children":[]}],"relativePath":"md/PDF批处理/880-批量pdf文件内容提取到excel工具-只支持文本类型-可模板定制.md","filePath":"md/PDF批处理/880-批量pdf文件内容提取到excel工具-只支持文本类型-可模板定制.md"}'),r={name:"md/PDF批处理/880-批量pdf文件内容提取到excel工具-只支持文本类型-可模板定制.md"};function a(e,l,s,p,g,h){return n(),o("div",null,[...l[0]||(l[0]=[i('<p>PDF信息提取工具专门用于从PDF发票和文档中提取结构化信息。采用模板匹配技术，可以通过可视化界面框选PDF中的关键区域，创建自定义提取模板，然后批量应用到多个PDF文件中，实现高效的信息提取。</p><p>可以用于批量发票信息提取，提取为excel文档，通过自定义模板自定义需要提前的信息。</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210175535177071733545666.png" alt=""></p><h3 id="功能特点" tabindex="-1">功能特点 <a class="header-anchor" href="#功能特点" aria-label="Permalink to &quot;功能特点&quot;">​</a></h3><ul><li><strong>可视化模板定制</strong>：通过图形化界面在PDF上直接框选需要提取的区域，为每个区域指定字段名称，直观便捷地创建提取模板</li><li><strong>模板管理功能</strong>：支持创建、编辑、删除和保存多个提取模板，方便不同类型发票的批量处理</li><li><strong>批量文件处理</strong>：支持递归扫描目录中的所有PDF文件，可选择保持目录结构或平铺处理，一次性处理大量文档</li><li><strong>拖放文件支持</strong>：支持直接拖放PDF文件到程序窗口，快速开始处理</li><li><strong>结果导出</strong>：提取结果可导出为Excel格式，便于后续数据分析和处理</li><li><strong>坐标系统转换</strong>：自动处理画布坐标与PDF坐标之间的转换，确保提取准确性</li></ul><h3 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h3><p><strong>首次使用流程</strong>：</p><ol><li><strong>启动程序</strong>：运行源代码文件，打开主界面</li><li><strong>打开PDF文件</strong>：点击”打开PDF”按钮或直接拖放PDF文件到窗口</li><li><strong>创建模板</strong>：切换到”模板定制”页面，在PDF预览中框选需要提取的区域</li><li><strong>保存模板</strong>：为框选区域指定字段名称后保存模板</li><li><strong>批量提取</strong>：切换回主页面，选择模板后批量处理PDF文件</li></ol><p><strong>关键操作步骤</strong>：</p><p>先自定义模板，通过加载pdf为同一类型的pdf制作模板，加载后会出现如图所示的预览界面</p><p>通过鼠标左键画框设置提前的区域，画框后会弹出一个窗口，用来命名</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210175744177071746497765.png" alt=""></p><p><strong>框选完成后一定要保存模板，不然之后无法调用</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210180203177071772330549.png" alt=""></p><p>配置完成模板后，选择此类型pdf所在文件夹进行操作即可，如果有多个模板，则选择对应的模板即可</p><ul><li><strong>框选区域</strong>：在图形化预览模式下，按住鼠标左键拖动绘制矩形框</li><li><strong>指定字段</strong>：框选完成后会弹出对话框，输入该区域对应的字段名称</li><li><strong>保存模板</strong>：点击”保存模板”按钮，为模板命名并保存</li><li><strong>批量处理</strong>：选择模板后，可打开单个文件或整个目录进行批量提取</li></ul><h3 id="详细使用说明" tabindex="-1">详细使用说明 <a class="header-anchor" href="#详细使用说明" aria-label="Permalink to &quot;详细使用说明&quot;">​</a></h3><h4 id="主界面功能" tabindex="-1">主界面功能 <a class="header-anchor" href="#主界面功能" aria-label="Permalink to &quot;主界面功能&quot;">​</a></h4><p>主界面包含以下主要功能区域：</p><ul><li><strong>文件操作区</strong>：提供打开PDF文件、打开目录、拖放文件等操作</li><li><strong>模板选择区</strong>：下拉菜单选择已保存的提取模板</li><li><strong>提取控制区</strong>：执行提取操作、查看提取结果</li><li><strong>结果显示区</strong>：显示提取到的字段信息</li></ul><h4 id="模板定制功能" tabindex="-1">模板定制功能 <a class="header-anchor" href="#模板定制功能" aria-label="Permalink to &quot;模板定制功能&quot;">​</a></h4><p>模板定制页面提供完整的模板编辑功能：</p><ul><li><strong>模板列表</strong>：左侧显示所有已保存的模板，支持新建、删除操作</li><li><strong>PDF预览区</strong>：中央区域显示PDF内容，支持翻页和缩放</li><li><strong>框选操作</strong>：鼠标拖动在PDF上绘制矩形框，标记提取区域</li><li><strong>字段管理</strong>：为每个框选区域指定对应的字段名称</li><li><strong>模板保存</strong>：将当前框选配置保存为模板</li></ul><h4 id="批量处理功能" tabindex="-1">批量处理功能 <a class="header-anchor" href="#批量处理功能" aria-label="Permalink to &quot;批量处理功能&quot;">​</a></h4><p>批量处理支持的模式：</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222195330177176121068196.png" alt=""></p><h4 id="结果导出" tabindex="-1">结果导出 <a class="header-anchor" href="#结果导出" aria-label="Permalink to &quot;结果导出&quot;">​</a></h4><p>提取完成后，可将结果导出为Excel文件，每个字段对应一列，每个PDF文件对应一行。</p><h3 id="使用场景示例" tabindex="-1">使用场景示例 <a class="header-anchor" href="#使用场景示例" aria-label="Permalink to &quot;使用场景示例&quot;">​</a></h3><h4 id="场景一-处理供应商发票" tabindex="-1">场景一：处理供应商发票 <a class="header-anchor" href="#场景一-处理供应商发票" aria-label="Permalink to &quot;场景一：处理供应商发票&quot;">​</a></h4><p>某公司每月收到大量供应商发票，需要提取发票号码、日期、金额等关键信息。使用本工具的步骤如下：</p><ol><li>打开一张典型的供应商发票PDF</li><li>在模板定制页面框选发票号码区域，命名为”发票号”</li><li>框选日期区域，命名为”开票日期”</li><li>框选金额区域，命名为”金额”</li><li>保存模板为”供应商发票模板”</li><li>选择该模板，打开包含所有发票的文件夹</li><li>执行批量提取，导出结果到Excel</li></ol><h4 id="场景二-整理报销单据" tabindex="-1">场景二：整理报销单据 <a class="header-anchor" href="#场景二-整理报销单据" aria-label="Permalink to &quot;场景二：整理报销单据&quot;">​</a></h4><p>财务部门需要从员工提交的报销单据中提取报销人、报销金额、报销类别等信息：</p><ol><li>打开一张报销单据PDF</li><li>框选员工姓名区域，命名为”报销人”</li><li>框选报销金额区域，命名为”报销金额”</li><li>框选报销类别区域，命名为”报销类别”</li><li>保存模板为”报销单据模板”</li><li>批量处理所有报销单据，生成Excel汇总表</li></ol><h4 id="场景三-合同信息归档" tabindex="-1">场景三：合同信息归档 <a class="header-anchor" href="#场景三-合同信息归档" aria-label="Permalink to &quot;场景三：合同信息归档&quot;">​</a></h4><p>法务部门需要从大量合同PDF中提取合同编号、签署日期、甲方乙方等信息：</p><ol><li>打开一份标准合同PDF</li><li>框选合同编号位置，命名为”合同编号”</li><li>框选签署日期位置，命名为”签署日期”</li><li>框选甲方乙方信息位置，分别命名</li><li>保存模板后批量处理所有合同文件</li><li>将提取结果导入数据库进行归档管理</li></ol><h3 id="注意事项" tabindex="-1">注意事项 <a class="header-anchor" href="#注意事项" aria-label="Permalink to &quot;注意事项&quot;">​</a></h3><ul><li><strong>重要警告</strong>：首次使用前请务必在少量样本文件上测试模板的准确性，确认无误后再进行批量处理</li><li><strong>模板兼容性</strong>：不同格式或版式的PDF文件需要创建不同的模板，模板不具有通用性</li><li><strong>文件备份</strong>：批量处理前建议备份原始PDF文件，防止意外数据丢失</li><li><strong>坐标精度</strong>：框选区域时尽量精确对齐文字边界，避免包含多余空白区域</li><li><strong>内存使用</strong>：处理大量PDF文件时可能占用较多内存，建议分批处理</li><li><strong>PDF质量</strong>：确保PDF文件清晰度足够，扫描件或低质量PDF可能影响提取准确性</li></ul><h3 id="程序截图" tabindex="-1">程序截图 <a class="header-anchor" href="#程序截图" aria-label="Permalink to &quot;程序截图&quot;">​</a></h3><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210175535177071733545666.png" alt=""></p><h3 id="效果展示" tabindex="-1">效果展示 <a class="header-anchor" href="#效果展示" aria-label="Permalink to &quot;效果展示&quot;">​</a></h3><p>只勾选穿透子文件夹</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210180322177071780251529.jpg" alt=""></p><p>同时勾选保持结构目录</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260222195330177176121078011.jpg" alt=""></p><p>同时勾选合并，即勾选穿透子文件夹和合并数据</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210180531177071793166364.jpg" alt=""></p><p>合并效果如图所示</p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210180624177071798420064.png" alt=""></p><h3 id="常见问题解答" tabindex="-1">常见问题解答 <a class="header-anchor" href="#常见问题解答" aria-label="Permalink to &quot;常见问题解答&quot;">​</a></h3><p><strong>Q: 框选区域后提取不到内容怎么办？</strong></p><p>A: 请检查以下几点：1) 确认框选区域准确覆盖了目标文字；2) 确认PDF文件清晰度足够；3) 尝试在文本模式下查看PDF内容，确认文字可被正确识别；4) 调整框选区域大小，避免包含过多空白。</p><p><strong>Q: 如何处理不同版式的PDF文件？</strong></p><p>A: 不同版式的PDF需要创建不同的模板。建议为每种版式创建专门的模板，处理时选择对应的模板。也可以在模板名称中加入版式标识，便于区分。</p><p><strong>Q: 批量处理时如何保持目录结构？</strong></p><p>A: 在打开目录时，勾选”保持目录结构”选项。这样输出结果会按照原始目录结构组织，每个文件夹的结果保存在对应的子目录中。</p><p><strong>Q: 提取结果可以导出为哪些格式？</strong></p><p>A: 目前支持导出为Excel格式（.xlsx），每个字段对应一列，每个PDF文件对应一行。</p><p><strong>Q: 如何删除不需要的模板？</strong></p><p>A: 在模板定制页面的模板列表中选中要删除的模板，点击”删除”按钮即可。删除操作不可恢复，请谨慎操作。</p><p><strong>Q: 程序支持哪些操作系统？</strong></p><p>A: 程序主要针对Windows系统开发，在Windows 7及以上版本上测试通过。</p><p><strong>Q: 处理大量文件时程序卡顿怎么办？</strong></p><p>A: 处理大量PDF文件时，建议分批处理，每批处理100-200个文件。同时关闭其他占用内存的程序，为Python分配足够的系统资源。</p><h3 id="程序使用环境及相关说明" tabindex="-1">程序使用环境及相关说明 <a class="header-anchor" href="#程序使用环境及相关说明" aria-label="Permalink to &quot;程序使用环境及相关说明&quot;">​</a></h3><p><strong>1、适用的系统环境说明</strong>： win7及以上64位win操作系统 ，  **注意事项：**win32位系统以及mac系统需要额外定制开发</p><p><strong>2、关于使用限制</strong>：①无需注册、登录等限制，直接使用，  ②没有电脑台数限制，  ③无使用时间限制、不联网本地使用、确保数据安全</p><p><strong>3、程序如何安装</strong>：不需要安装，按照说明使用即可。</p><p><strong>特别注意</strong>：请先测试，注意备份原文件，之后再批量使用，避免不可逆损失。</p><h3 id="程序使用说明" tabindex="-1">程序使用说明 <a class="header-anchor" href="#程序使用说明" aria-label="Permalink to &quot;程序使用说明&quot;">​</a></h3><p><strong>解压后，双击快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210175234177071715482678.png" alt=""></p><p><strong>如果快捷方式失效，打开文件夹，找到如下文件，重新创建快捷方式使用即可</strong></p><p><img src="https://www.softbangong.com/wp-content/uploads/2026/04/20260210175323177071720340023.png" alt=""></p><hr><p><strong>程序下载链接：</strong> <a href="https://www.softbangong.com/2460.html" target="_blank" rel="noreferrer">https://www.softbangong.com/2460.html</a></p>',78)])])}const u=t(r,[["render",a]]);export{d as __pageData,u as default};
